/**
 * The frames the static product views draw: one representative moment of each demo, taken from the same engines and
 * scenario data as the interactive islands. `frames/{cli,ide,harness}.json` are generated by `frames.test.ts` (run with UPDATE_FRAMES=1) and the
 * same test fails when they no longer match what the engines produce, so a view can never drift from the scenario.
 * Keeping the result as data means a page that only shows the views does not ship the engines or the scenario files, and one file per
 * product means a page that shows only the cli view does not ship the ide and harness frames.
 */
import type { CliBlock } from '../cli';
import type { HarnessSession, JournalEntry } from '../harness';
import type { ChatItem, TreeEntry } from '../ide';
import cliData from './frames/cli.json';
import harnessData from './frames/harness.json';
import ideData from './frames/ide.json';

export interface CliFrame {
  provider: string;
  cwd: string;
  title: string;
  sessionId: string;
  write: boolean;
  /** Fixed launch grant in a recorded CLI session, when supplied by its source. */
  shell?: boolean;
  agents: number;
  models: number;
  tools: number;
  blocks: CliBlock[];
  /** Key and label pairs, from labels.json. */
  hints: [string, string][];
}

export interface IdeFrame {
  agent: string;
  chatTitle: string;
  /** The model label. Replies are scripted. */
  model: string;
  openFiles: string[];
  active: string;
  tree: TreeEntry[];
  file: { path: string; lang: string; text: string };
  /** Zero-based lines changed by the accepted edit. */
  changed: number[];
  chat: ChatItem[];
}

export interface HarnessFrame {
  limit: number;
  commands: number;
  stats: { running: number; queued: number; done: number; commandsHeld: number };
  sessions: HarnessSession[];
  journal: JournalEntry[];
  sample: { id: string; label: string; caption: string; code: string };
}

export interface Frames {
  cli: CliFrame;
  ide: IdeFrame;
  harness: HarnessFrame;
}

export const cliFrame = cliData as unknown as CliFrame;
export const ideFrame = ideData as unknown as IdeFrame;
export const harnessFrame = harnessData as unknown as HarnessFrame;

/** All three. A view imports its own frame instead, so a page that shows one product does not bundle the others. */
export const frames: Frames = { cli: cliFrame, ide: ideFrame, harness: harnessFrame };
